(()=>{const buttons=[...document.querySelectorAll('[data-railway-tool]')];const copy={"railway-generation":{problem:"Railway bungalows are recurring, static landmarks useful for train localization in the U.S., but available point-cloud datasets are not large or reliable enough for training and testing.",solution:"I generate multimodal railway datasets in Blender: scene images, 3D point clouds, and aligned object labels for detector training."},"railway-evaluation":{problem:"A detector trained on synthetic scenes can fail on real railway data: my initial synthetic-to-OSDAR result was 0% mAP.",solution:"I tested multiple 3D detectors, including CenterPoint, and brought synthetic-to-OSDAR performance to 51.89% mAP at 3D IoU 0.5."}};function select(button){buttons.forEach(b=>{const open=b===button;b.setAttribute('aria-expanded',String(open));b.querySelector('b').textContent=open?'−':'+';document.getElementById(b.dataset.railwayTool).hidden=!open});const c=copy[button.dataset.railwayTool];document.querySelector('#railway-problem').textContent=c.problem;document.querySelector('#railway-solution').textContent=c.solution;}buttons.forEach((b,i)=>{b.addEventListener('click',()=>select(b));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const j=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[j].focus();select(buttons[j])})});function hashView(){if(location.hash==='#railway-evaluation')select(buttons[1]);else if(location.hash==='#langgraph-heading'||location.hash==='#railway-generation')select(buttons[0])}addEventListener('hashchange',hashView);hashView()})();
